"""Job runner."""


class Runner:
    def __init__(self, max_per_tenant=2):
        self.max_per_tenant = max_per_tenant
        self._q = []
        self._results = []
        self._failed = 0
        self._last = None
        self._streak = 0
        self._order = 0

    def submit(self, tenant, fn, *, priority=0):
        self._q.append((tenant, fn, priority, self._order))
        self._order += 1

    def run(self, limit=None):
        results = []
        count = 0
        while self._q and (limit is None or count < limit):
            eligible = []
            for job in self._q:
                tenant = job[0]
                if self._last is not None and tenant == self._last and self._streak >= self.max_per_tenant:
                    continue
                eligible.append(job)

            if eligible:
                eligible.sort(key=lambda j: (-j[2], j[3]))
                chosen = eligible[0]
            else:
                self._q.sort(key=lambda j: (-j[2], j[3]))
                chosen = self._q[0]

            self._q.remove(chosen)

            tenant, fn, priority, order = chosen
            try:
                result = fn()
                results.append(result)
            except Exception as e:
                results.append({'ok': False, 'error': str(e)})
                self._failed += 1

            if tenant == self._last:
                self._streak += 1
            else:
                self._last = tenant
                self._streak = 1

            self._results.append(results[-1])
            count += 1

        return results

    def stats(self):
        return {
            'run': len(self._results),
            'failed': self._failed,
            'skipped': len(self._q),
        }

    def pending(self):
        return len(self._q)

    def reset(self):
        self._q = []
        self._last = None
        self._streak = 0
        self._order = 0
