"""Expression parser."""
import re


class ExprError(Exception):
    pass


def tokenize(text):
    if not text or not text.strip():
        raise ExprError("empty input")

    tokens = []
    i = 0
    while i < len(text):
        if text[i].isspace():
            i += 1
            continue

        if text[i].isdigit() or text[i] == '.':
            m = re.match(r'\d+\.?\d*|\.\d+', text[i:])
            if not m:
                raise ExprError(f"bad token at position {i}")
            token_str = m.group()
            if '.' in token_str:
                tokens.append(float(token_str))
            else:
                tokens.append(int(token_str))
            i += len(token_str)
            continue

        if text[i:i+2] in ('**', '//'):
            tokens.append(text[i:i+2])
            i += 2
            continue

        if text[i] in '+-*/%()':
            tokens.append(text[i])
            i += 1
            continue

        raise ExprError(f"bad token at position {i}")

    if not tokens:
        raise ExprError("empty input")

    return tokens


def parse(text):
    tokens = tokenize(text)
    result, pos = _parse_expr(tokens, 0)
    if pos != len(tokens):
        raise ExprError("trailing junk")
    return result


def _parse_expr(tokens, pos):
    left, pos = _parse_term(tokens, pos)
    while pos < len(tokens) and tokens[pos] in ('+', '-'):
        op = tokens[pos]
        pos += 1
        right, pos = _parse_term(tokens, pos)
        if op == '+':
            left = left + right
        else:
            left = left - right
    return left, pos


def _parse_term(tokens, pos):
    left, pos = _parse_factor(tokens, pos)
    while pos < len(tokens) and tokens[pos] in ('*', '/', '//', '%'):
        op = tokens[pos]
        pos += 1
        right, pos = _parse_factor(tokens, pos)
        if op == '*':
            left = left * right
        elif op == '/':
            if right == 0:
                raise ExprError("division by zero")
            left = left / right
        elif op == '//':
            if right == 0:
                raise ExprError("division by zero")
            left = left // right
        elif op == '%':
            if right == 0:
                raise ExprError("division by zero")
            left = left % right
    return left, pos


def _parse_factor(tokens, pos):
    if pos < len(tokens) and tokens[pos] in ('+', '-'):
        op = tokens[pos]
        pos += 1
        val, pos = _parse_factor(tokens, pos)
        if op == '-':
            val = -val
        return val, pos
    return _parse_power(tokens, pos)


def _parse_power(tokens, pos):
    base, pos = _parse_atom(tokens, pos)
    if pos < len(tokens) and tokens[pos] == '**':
        pos += 1
        exp, pos = _parse_factor(tokens, pos)
        base = base ** exp
    return base, pos


def _parse_atom(tokens, pos):
    if pos >= len(tokens):
        raise ExprError("unexpected end of expression")
    token = tokens[pos]
    if isinstance(token, (int, float)):
        return token, pos + 1
    if token == '(':
        pos += 1
        val, pos = _parse_expr(tokens, pos)
        if pos >= len(tokens) or tokens[pos] != ')':
            raise ExprError("unbalanced parentheses")
        pos += 1
        return val, pos
    raise ExprError(f"unexpected token: {token}")
