"""Webhook processing."""


class Processor:
    def __init__(self):
        self._done = {}
        self._in_progress = set()

    def process(self, event_id, handler):
        if event_id in self._done:
            return {'ok': True, 'duplicate': True}
        if event_id in self._in_progress:
            return {'ok': True, 'duplicate': True}

        self._in_progress.add(event_id)
        try:
            r = handler(event_id)
        except BaseException:
            self._in_progress.discard(event_id)
            raise

        self._in_progress.discard(event_id)

        if not r:
            return {'ok': False, 'duplicate': False}

        self._done[event_id] = r
        return {'ok': True, 'duplicate': False}

    def result(self, event_id):
        return self._done.get(event_id)

    def seen(self, event_id):
        return event_id in self._done

    def forget(self, event_id):
        if event_id in self._done:
            del self._done[event_id]
            return True
        return False

    def processed_count(self):
        return len(self._done)

    def clear(self):
        self._done.clear()
        self._in_progress.clear()
