"""Dependency graph."""


class Graph:
    def __init__(self):
        self._mods = {}

    def add_module(self, name, provides=(), requires=()):
        self._mods[name] = (set(provides), set(requires))

    def dependents(self, name):
        return sorted(m for m, (_, req) in self._mods.items() if name in req)

    def _module_deps(self, name):
        """Modules that directly depend on module *name* (symbol-resolved)."""
        provides = self._mods[name][0]
        result = set()
        for m, (_, req) in self._mods.items():
            if name in req or (req & provides):
                result.add(m)
        return result

    def _reverse_closure(self, name):
        if name in self._mods:
            start = {name}
        else:
            start = {m for m, (prov, _) in self._mods.items() if name in prov}
        if not start:
            return set()
        visited = set(start)
        queue = list(start)
        while queue:
            cur = queue.pop()
            for dep in self._module_deps(cur):
                if dep not in visited:
                    visited.add(dep)
                    queue.append(dep)
        return visited

    def invalidate(self, name):
        to_remove = self._reverse_closure(name)
        for m in to_remove:
            del self._mods[m]
        return to_remove

    def reverse_closure(self, name):
        return self._reverse_closure(name)

    def missing(self):
        all_requires = set()
        all_provides = set()
        for prov, req in self._mods.values():
            all_requires |= req
            all_provides |= prov
        return sorted(all_requires - all_provides)

    def cycles(self):
        adj = {m: self._module_deps(m) for m in self._mods}
        nodes = sorted(self._mods.keys())
        found = set()

        def dfs(start, current, path, visited):
            for nxt in adj.get(current, set()):
                if nxt < start:
                    continue
                if nxt == start:
                    found.add(tuple(sorted(path)))
                elif nxt not in visited:
                    visited.add(nxt)
                    path.append(nxt)
                    dfs(start, nxt, path, visited)
                    path.pop()
                    visited.discard(nxt)

        for start in nodes:
            dfs(start, start, [start], {start})

        return sorted(found)

    def to_json(self):
        return {
            name: {
                'provides': sorted(prov),
                'requires': sorted(req),
            }
            for name, (prov, req) in self._mods.items()
        }
