"""Config merge."""
from types import MappingProxyType


class _Drop:
    def __repr__(self):
        return 'DROP'

    def __eq__(self, other):
        return isinstance(other, _Drop)

    def __hash__(self):
        return hash('DROP')


DROP = _Drop()


def _deep_copy(obj):
    if isinstance(obj, dict):
        return {k: _deep_copy(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [_deep_copy(v) for v in obj]
    return obj


def _remove_path(cfg, parts):
    """Remove a nested key given path parts. Mutates cfg (which is already a copy)."""
    cur = cfg
    for part in parts[:-1]:
        if not isinstance(cur, dict) or part not in cur:
            return
        cur = cur[part]
    if isinstance(cur, dict):
        cur.pop(parts[-1], None)


def _merge_recursive(base, layer, lists):
    out = _deep_copy(base)
    for k, v in layer.items():
        if isinstance(v, _Drop):
            if '.' in k:
                _remove_path(out, k.split('.'))
            else:
                out.pop(k, None)
            continue

        if k in out and isinstance(out[k], dict) and isinstance(v, dict):
            out[k] = _merge_recursive(out[k], v, lists)
        elif k in out and isinstance(out[k], list) and isinstance(v, list):
            if lists == 'replace':
                out[k] = _deep_copy(v)
            elif lists == 'concat':
                out[k] = out[k] + _deep_copy(v)
            elif lists == 'unique':
                combined = out[k] + _deep_copy(v)
                seen = []
                for item in combined:
                    if item not in seen:
                        seen.append(item)
                out[k] = seen
            else:
                out[k] = _deep_copy(v)
        else:
            out[k] = _deep_copy(v)
    return out


def merge(base, *layers, lists='replace'):
    out = _deep_copy(base)
    for layer in layers:
        out = _merge_recursive(out, layer, lists)
    return out


def deep_get(cfg, path, default=None):
    cur = cfg
    for part in path.split('.'):
        if not isinstance(cur, dict) or part not in cur:
            return default
        cur = cur[part]
    return cur


def deep_set(cfg, path, value):
    parts = path.split('.')

    def _set(cur, remaining):
        if not remaining:
            return value
        key = remaining[0]
        rest = remaining[1:]
        if isinstance(cur, dict):
            new_cur = dict(cur)
        else:
            new_cur = {}
        if rest:
            child = new_cur.get(key)
            if not isinstance(child, dict):
                child = {}
            new_cur[key] = _set(child, rest)
        else:
            new_cur[key] = value
        return new_cur

    return _set(cfg, parts)


def freeze(cfg):
    if isinstance(cfg, dict):
        return MappingProxyType({k: freeze(v) for k, v in cfg.items()})
    if isinstance(cfg, list):
        return tuple(freeze(v) for v in cfg)
    return cfg
